mapper.select:
SELECT g.id, g.name, g.storage, g.goodsType, g.count, g.reserved_count AS reservedCount, g.min_count AS minCount, g.barcode, g.specs, g.unit, g.retail_price AS retailPrice, g.purchase_price AS purchasePrice, g.supplier_id AS supplierId, s.name AS supplierName, gt.name AS categoryName, st.name AS warehouseName, g.remark FROM goods g LEFT JOIN supplier s ON g.supplier_id = s.id LEFT JOIN goodstype gt ON g.goodsType = gt.id LEFT JOIN storage st ON g.storage = st.id
AND g.name LIKE CONCAT('%', #{name}, '%')
AND g.goodsType = #{goodsType}
AND g.storage = #{storage}
AND g.supplier_id = #{supplierId}
AND (g.count - COALESCE(g.reserved_count, 0)) <= g.min_count
ORDER BY g.id DESC

SELECT gb.id AS batchId, gb.goods_id AS goodsId, g.name AS goodsName, gb.supplier_id AS supplierId, s.name AS supplierName, gb.storage_id AS storageId, st.name AS storageName, gb.batch_no AS batchNum, gb.purchase_price AS purchasePrice, gb.initial_count AS initialCount, gb.current_count AS currentCount, gb.create_time AS createTime FROM goods_batch gb INNER JOIN goods g ON gb.goods_id = g.id LEFT JOIN supplier s ON gb.supplier_id = s.id LEFT JOIN storage st ON gb.storage_id = st.id
AND g.name LIKE CONCAT('%', #{goodsName}, '%')
AND gb.supplier_id = #{supplierId}
AND gb.storage_id = #{storageId}
AND gb.batch_no LIKE CONCAT('%', #{batchNo}, '%')
ORDER BY gb.create_time DESC
